import hashlib,json
from pathlib import Path
def verify(folder):
 e=Path(folder);m=json.loads((e/'manifest.json').read_text());assert set(m['files'])=={str(p.relative_to(e)) for p in e.rglob('*') if p.is_file() and p!=e/'manifest.json'}
 for n,x in m['files'].items():
  assert not Path(n).is_absolute() and '..' not in Path(n).parts;p=e/n;assert not p.is_symlink();raw=p.read_bytes();assert len(raw)==x['bytes'] and hashlib.sha256(raw).hexdigest()==x['sha256']
 failure=json.loads((e/'retained-failure.json').read_text());assert failure=={'observer_error':'OSError: Cannot observe a live owned root','cleanup_error':'PermissionError: [Errno 1] Operation not permitted','native_post_root_observer_qualified':False,'cold_build_attempted':False,'producer_retry':False,'spent_root_roles':2,'finite_child_finished':True};assert not (e/'build.json').exists() and not (e/'cache').exists()
 root=json.loads((e/'detached/root.json').read_text());done=json.loads((e/'detached/child-finished.json').read_text());assert root['pid']==root['group']==done['original_parent'] and root['child_pid']==done['pid']==done['group'] and root['pid']!=root['child_pid'] and done['self_terminated'] is True and done['bytes']==32;assert (e/'detached/heartbeat.bin').read_bytes()==bytes(range(32))
 control=json.loads((e/'denied-control/result.json').read_text());assert control['failure']=={'type':'RuntimeError','message':'Owned observer unavailable control','cleanup_errors':["group_signal: PermissionError(1, 'Owned signal denied control')"]} and control['root_exit_code']==0 and type(control['root_exit_code']) is int and 0<control['elapsed_seconds']<2 and control['actual_signal_sent'] is False and control['marker_bytes']==8 and control['attempts']==[{'pid':control['root_pid'],'signal':9,'injected_permission_error':True}];assert control['root_pid']>1 and control['root_pid'] not in [root['pid'],root['child_pid']] and (e/'denied-control/finished.bin').read_bytes()==b'finished'
 plain=json.loads((e/'plain.json').read_text());assert plain=={'code':0,'stdout':'owned clean root\n','stderr':''}
 env=json.loads((e/'environment.json').read_text());assert env['total_root_roles']==4 and env['observer_binary_sha256']=='718c0dd47aaa6598281d0f0afb7dd12fa4c497a8494897b24829905de82ecda5';rea=json.loads((e/'rea-status.json').read_text());assert rea['server_identity']['server']['version']=='6.2.0'
 source=(e/'sourcecache-after-cleanup.py').read_text();assert 'except BaseException as failure:' in source and 'failure.compiler_cleanup_errors=tuple(cleanup_errors)' in source and 'try:process.wait(timeout=2)' in source
 return {'root_roles':4,'controlled_bytes':57,'original_failure_preserved':True,'denied_signal_root_wait_qualified':True,'native_observer_qualified':False,'cold_build_attempted':False}
